// The Tool Bridge contract, answered by n8n.
//
// In : the closed request envelope of capsule_engine/bridge.py
//       {bridge_version, gear, request_id, issued_at, deadline_ms,
//        input_sha256, capsule, governance, input}
// Out: the closed response envelope. The bridge verifies every field here,
//      so anything this node invents is refused rather than delivered:
//        - gear and request_id must echo the request (correlation)
//        - status must be one of ok / refused / error
//        - output.channel must EQUAL input.channel (a gear may not redirect)
//        - output.receipt_id is the delivery proof recorded on the capsule
//
// Do not add keys. The bridge closes over the schema; an unknown key inside
// `output` is a protocol violation, not a bonus field.

const item = $input.first().json || {};
const body = item.body || item;
const headers = item.headers || {};

const gear = body.gear || 'social:publish';
const requestId = body.request_id || '';
const input = body.input || {};
const channel = input.channel || '';
const text = typeof input.text === 'string' ? input.text : '';

function answer(status, output, refusal) {
  const envelope = {
    bridge_version: 1,
    gear: gear,
    request_id: requestId || 'unknown',
    status: status,
    output: output || {},
    usage: {},
    engine: { tool: 'n8n' }
  };
  if (refusal) {
    envelope.refusal = refusal;
  }
  return [{ json: envelope }];
}

// The token never travels in the envelope, by design: it is an Authorization
// header. Fail closed when it is absent or wrong.
const sent = String(headers.authorization || headers.Authorization || '');
const expected = 'Bearer ' + String($env.AGENCY_BRIDGE_TOKEN || '');
if (expected === 'Bearer ') {
  return answer('refused', {}, {
    code: 'not_configured',
    detail: 'AGENCY_BRIDGE_TOKEN is not set inside the n8n container'
  });
}
if (sent !== expected) {
  return answer('refused', {}, {
    code: 'unauthorized',
    detail: 'missing or wrong Authorization bearer token'
  });
}

if (gear !== 'social:publish') {
  return answer('refused', {}, {
    code: 'unsupported_gear',
    detail: 'this workflow speaks social:publish only, got ' + gear
  });
}
if (!requestId || !channel || !text) {
  return answer('refused', {}, {
    code: 'bad_request',
    detail: 'request_id, input.channel and input.text are all required'
  });
}

// --- the delivery -------------------------------------------------------
// A real channel adapter belongs here (LinkedIn API, Meta Graph, a queue).
// Today this is the honest stub: it accepts the post and returns a receipt
// that binds this execution and the channel, so the receipt recorded on the
// capsule can be traced back to one n8n execution.
return answer('ok', {
  receipt_id: 'n8n-' + $execution.id + '-' + channel,
  channel: channel,
  published_at: new Date().toISOString()
});
